import { execSync } from 'child_process';

const log = (msg) => console.log('\x1b[34m' + msg + '\x1b[0m');
const success = (msg) => console.log('\x1b[32m' + msg + '\x1b[0m');
const error = (msg) => console.log('\x1b[31m' + msg + '\x1b[0m');

async function runStep(name, command) {
    log(`\n[${name.toUpperCase().padEnd(12)}]  ${command.padEnd(40)}`);
    try {
        const start = Date.now();
        execSync(command, { stdio: 'inherit' });
        const duration = ((Date.now() - start) / 1000).toFixed(2);
        success(`PASS   ${duration}s`);
    } catch (e) {
        error(`FAIL`);
        process.exit(1);
    }
}

async function verify() {
    console.log('\x1b[1m' + '═'.repeat(72));
    console.log('  🔬  VAHI ADMIN VERIFICATION PIPELINE');
    console.log('  ' + new Date().toLocaleString());
    console.log('═'.repeat(72) + '\x1b[0m');

    await runStep('Lint', 'pnpm lint');
    await runStep('Build', 'pnpm build');

    console.log('\x1b[32m\x1b[1m\n✅  ADMIN VERIFICATION COMPLETE\n\x1b[0m');
}

verify();

"use client";

import React, { useState, useEffect } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/Card";
import { History, RefreshCw } from "lucide-react";
import { DataTable } from "@/components/ui/DataTable";
import { Button } from "@/components/ui/Button";
import { api } from "@/lib/api";
import { cn } from "@/lib/utils";

export default function AuditLogsPage() {
    const [isLoading, setIsLoading] = useState(true);
    const [logs, setLogs] = useState<any[]>([]);

    useEffect(() => {
        loadLogs();
    }, []);

    const loadLogs = async () => {
        setIsLoading(true);
        try {
            const res = await api.get<{ ok: boolean, logs: any[] }>("/admin/audit-logs");
            setLogs(res.data.logs);
        } catch (error) {
            console.error("Failed to load logs", error);
        } finally {
            setIsLoading(false);
        }
    };

    const columns = [
        { header: "Timestamp", accessorKey: "time" },
        { header: "Actor", accessorKey: "actor" },
        { header: "Action", accessorKey: "action" },
        { header: "Entity", accessorKey: "entity" },
        { header: "Status", accessorKey: "status" },
    ];

    return (
        <div className="space-y-6 animate-in slide-in-from-bottom-2 duration-500">
            <div className="flex flex-col gap-1">
                <h1 className="text-3xl font-bold tracking-tight">Audit Logs</h1>
                <p className="text-muted-foreground">Traceability and security logs for across all system modules.</p>
            </div>

            <div className="flex items-center gap-4 py-2">
                <Button variant="outline" className="rounded-full px-6">All Activities</Button>
                <Button variant="ghost" className="rounded-full px-6 text-muted-foreground">Security</Button>
                <Button variant="ghost" className="rounded-full px-6 text-muted-foreground">Data Changes</Button>
                <Button variant="ghost" className="rounded-full px-6 text-muted-foreground">System</Button>
            </div>

            <Card className="border-none shadow-sm bg-card/60">
                <CardHeader>
                    <div className="flex items-center justify-between">
                        <CardTitle className="text-lg font-bold flex items-center gap-2">
                            <History className="h-5 w-5 text-primary" />
                            Recent Activity
                        </CardTitle>
                        <div className="flex items-center gap-2">
                            <Button variant="ghost" size="sm" onClick={loadLogs} disabled={isLoading}>
                                <RefreshCw className={cn("h-4 w-4 mr-2", isLoading && "animate-spin")} />
                                Refresh
                            </Button>
                            <Button variant="ghost" size="sm">Download CSV</Button>
                            <Button variant="ghost" size="sm" className="text-destructive">Clear Logs</Button>
                        </div>
                    </div>
                </CardHeader>
                <CardContent className="p-0">
                    <DataTable
                        columns={columns}
                        data={logs}
                        isLoading={isLoading}
                        searchPlaceholder="Search logs by actor or action..."
                    />
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { DataTable } from "@/components/ui/DataTable";
import { Card, CardContent } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Plus, Megaphone, Users, Target } from "lucide-react";
import { Offer, offerService } from "@/services/offerService";
import { useToast } from "@/components/ui/Toast";
import { OfferDrawer } from "@/components/banners/OfferDrawer";
import { Switch } from "@/components/ui/Switch";

export default function BannersPage() {
    const [offers, setOffers] = useState<Offer[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isDrawerOpen, setIsDrawerOpen] = useState(false);
    const [selectedOffer, setSelectedOffer] = useState<Offer | undefined>(undefined);
    const { toast } = useToast();

    const fetchOffers = async () => {
        setIsLoading(true);
        try {
            const data = await offerService.getAll();
            setOffers(data);
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to fetch offers",
                type: "error"
            });
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchOffers();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const handleEdit = (offer: Offer) => {
        setSelectedOffer(offer);
        setIsDrawerOpen(true);
    };

    const handleCreate = () => {
        setSelectedOffer(undefined);
        setIsDrawerOpen(true);
    };

    const handleToggleActive = async (id: string, currentStatus: boolean) => {
        try {
            await offerService.toggleActive(id, !currentStatus);
            toast({
                title: "Success",
                description: `Offer ${!currentStatus ? "activated" : "deactivated"} successfully`,
                type: "success"
            });
            fetchOffers();
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to toggle offer status",
                type: "error"
            });
        }
    };

    const columns = [
        {
            header: "Offer / Banner",
            accessorKey: "title",
            cell: (offer: Offer) => (
                <div className="flex items-center gap-3">
                    <div className="h-10 w-10 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
                        <Megaphone className="h-5 w-5" />
                    </div>
                    <div>
                        <p className="font-semibold">{offer.title}</p>
                        <p className="text-xs text-muted-foreground truncate max-w-[250px]">{offer.message}</p>
                    </div>
                </div>
            )
        },
        {
            header: "Audience",
            accessorKey: "audience",
            cell: (offer: Offer) => (
                <div className="flex items-center gap-1.5 text-xs font-medium px-2.5 py-1 rounded-full bg-muted w-fit">
                    <Users className="h-3 w-3" />
                    {offer.audience.replace("_", " ")}
                </div>
            )
        },
        {
            header: "Priority",
            accessorKey: "priority",
            cell: (offer: Offer) => (
                <div className="flex items-center gap-1">
                    <Target className="h-4 w-4 text-muted-foreground" />
                    <span className="font-medium">{offer.priority}</span>
                </div>
            )
        },
        {
            header: "Status",
            accessorKey: "isActive",
            cell: (offer: Offer) => (
                <div className="flex items-center gap-2">
                    <Switch
                        checked={offer.isActive}
                        onCheckedChange={() => handleToggleActive(offer.id, offer.isActive)}
                    />
                    <span className={offer.isActive ? "text-green-600 font-semibold text-[10px] uppercase tracking-wider" : "text-muted-foreground font-semibold text-[10px] uppercase tracking-wider"}>
                        {offer.isActive ? "Live" : "Draft"}
                    </span>
                </div>
            )
        },
        {
            header: "Actions",
            accessorKey: "actions",
            className: "text-right",
            cell: (offer: Offer) => (
                <Button variant="ghost" size="sm" onClick={(e) => {
                    e.stopPropagation();
                    handleEdit(offer);
                }}>
                    Edit
                </Button>
            )
        }
    ];

    return (
        <div className="space-y-6">
            <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight text-foreground">Banners & Offers</h1>
                    <p className="text-muted-foreground">Manage system-wide promotional banners and notifications.</p>
                </div>
                <Button onClick={handleCreate} className="h-11 px-6 shadow-lg shadow-primary/20">
                    <Plus className="mr-2 h-5 w-5" />
                    Create Offer
                </Button>
            </div>

            <Card className="border-none shadow-none bg-transparent">
                <CardContent className="p-0">
                    <DataTable
                        columns={columns}
                        data={offers}
                        isLoading={isLoading}
                        onRowClick={handleEdit}
                        emptyMessage="No active offers or banners found."
                    />
                </CardContent>
            </Card>

            <OfferDrawer
                isOpen={isDrawerOpen}
                onClose={() => setIsDrawerOpen(false)}
                offer={selectedOffer}
                onSuccess={fetchOffers}
            />
        </div>
    );
}

"use client";

import React from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/Card";
import {
    Box,
    Package,
    AlertTriangle,
    TrendingUp,
    Search,
    History,
    ArrowRight
} from "lucide-react";
import { DataTable } from "@/components/ui/DataTable";
import { Button } from "@/components/ui/Button";
import { cn } from "@/lib/utils";

export default function InventoryPage() {
    const stats = [
        { title: "Total SKUs", value: "84,200", icon: Package, label: "Live across network" },
        { title: "Low Stock Alerts", value: "1,240", icon: AlertTriangle, label: "Needs attention" },
        { title: "Stock Value", value: "₹18.4Cr", icon: TrendingUp, label: "Estimated" },
        { title: "Recent Movements", value: "4.2K", icon: History, label: "Past 24 hours" },
    ];

    const columns = [
        { header: "Item Name", accessorKey: "name" },
        { header: "Category", accessorKey: "category" },
        { header: "Total Stock", accessorKey: "stock" },
        { header: "Avg Price", accessorKey: "price" },
        { header: "Organization", accessorKey: "org" },
    ];

    const data = [
        { id: "1", name: "Premium Widget", category: "ELECTRONICS", stock: "1,450", price: "₹899", org: "Global Retail" },
        { id: "2", name: "Iron Rod 12mm", category: "HARDWARE", stock: "482", price: "₹55", org: "Durga Steels" },
        { id: "3", name: "Cotton Blend Fabric", category: "TEXTILES", stock: "12,400m", price: "₹120", org: "Fabrics India" },
    ];

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex flex-col gap-1">
                <h1 className="text-3xl font-bold tracking-tight">Global Inventory</h1>
                <p className="text-muted-foreground text-lg">System-wide monitoring of stock levels and item data.</p>
            </div>

            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-4">
                {stats.map((stat, i) => (
                    <Card key={i} className="border-none shadow-sm bg-muted/20 hover:bg-muted/30 transition-colors">
                        <CardHeader className="flex flex-row items-center justify-between pb-2">
                            <CardTitle className="text-sm font-semibold text-muted-foreground">{stat.title}</CardTitle>
                            <stat.icon className={cn("h-4 w-4", stat.title.includes("Alert") ? "text-orange-600" : "text-primary")} />
                        </CardHeader>
                        <CardContent>
                            <div className="text-2xl font-bold">{stat.value}</div>
                            <p className="text-xs text-muted-foreground mt-1">{stat.label}</p>
                        </CardContent>
                    </Card>
                ))}
            </div>

            <Card className="border-none shadow-sm bg-card/50 overflow-hidden">
                <CardHeader className="flex flex-row items-center justify-between">
                    <CardTitle className="text-lg font-bold">Item Distribution</CardTitle>
                    <Button variant="ghost" className="gap-2 text-primary font-bold">
                        View Detailed Metrics
                        <ArrowRight className="h-4 w-4" />
                    </Button>
                </CardHeader>
                <CardContent className="p-0">
                    <DataTable
                        columns={columns}
                        data={data}
                        searchPlaceholder="Filter items by name or category..."
                    />
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { DataTable } from "@/components/ui/DataTable";
import { Card, CardContent } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Plus, Store, CheckCircle2, XCircle } from "lucide-react";
import { Organization, organizationService } from "@/services/organizationService";
import { useToast } from "@/components/ui/Toast";
import { OrganizationDrawer } from "@/components/organizations/OrganizationDrawer";

export default function OrganizationsPage() {
    const [organizations, setOrganizations] = useState<Organization[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState("");
    const [isDrawerOpen, setIsDrawerOpen] = useState(false);
    const [selectedOrg, setSelectedOrg] = useState<Organization | undefined>(undefined);
    const { toast } = useToast();

    const fetchOrganizations = async () => {
        setIsLoading(true);
        try {
            const data = await organizationService.getAll();
            setOrganizations(data);
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to fetch organizations",
                type: "error"
            });
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchOrganizations();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const filteredOrgs = organizations.filter(org =>
        org.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        org.code.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const handleEdit = (org: Organization) => {
        setSelectedOrg(org);
        setIsDrawerOpen(true);
    };

    const handleCreate = () => {
        setSelectedOrg(undefined);
        setIsDrawerOpen(true);
    };

    const columns = [
        {
            header: "Organization",
            accessorKey: "name",
            cell: (org: Organization) => (
                <div className="flex items-center gap-3">
                    <div className="h-10 w-10 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
                        <Store className="h-5 w-5" />
                    </div>
                    <div>
                        <p className="font-semibold">{org.name}</p>
                        <p className="text-xs text-muted-foreground">{org.code}</p>
                    </div>
                </div>
            )
        },
        {
            header: "GST Number",
            accessorKey: "gstNumber",
            cell: (org: Organization) => org.gstNumber || "N/A"
        },
        {
            header: "Contact",
            accessorKey: "phoneNumber",
            cell: (org: Organization) => (
                <div className="text-xs space-y-0.5">
                    <p>{org.phoneNumber || "No Phone"}</p>
                    <p className="text-muted-foreground">{org.email || "No Email"}</p>
                </div>
            )
        },
        {
            header: "Status",
            accessorKey: "isActive",
            cell: (org: Organization) => (
                <div className={org.isActive ? "text-green-600 flex items-center gap-1.5" : "text-red-500 flex items-center gap-1.5"}>
                    {org.isActive ? <CheckCircle2 className="h-4 w-4" /> : <XCircle className="h-4 w-4" />}
                    <span className="text-xs font-semibold uppercase tracking-wider">{org.isActive ? "Active" : "Inactive"}</span>
                </div>
            )
        },
        {
            header: "Actions",
            accessorKey: "actions",
            className: "text-right",
            cell: (org: Organization) => (
                <Button variant="ghost" size="sm" onClick={(e) => {
                    e.stopPropagation();
                    handleEdit(org);
                }}>
                    Edit
                </Button>
            )
        }
    ];

    return (
        <div className="space-y-6">
            <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Organizations</h1>
                    <p className="text-muted-foreground">Manage all registered businesses in the system.</p>
                </div>
                <Button onClick={handleCreate} className="h-11 px-6 shadow-lg shadow-primary/20">
                    <Plus className="mr-2 h-5 w-5" />
                    Create Organization
                </Button>
            </div>

            <Card className="border-none shadow-none bg-transparent">
                <CardContent className="p-0">
                    <DataTable
                        columns={columns}
                        data={filteredOrgs}
                        isLoading={isLoading}
                        onRowClick={handleEdit}
                        searchPlaceholder="Filter by name or code..."
                        searchValue={searchQuery}
                        onSearchChange={setSearchQuery}
                    />
                </CardContent>
            </Card>

            <OrganizationDrawer
                isOpen={isDrawerOpen}
                onClose={() => setIsDrawerOpen(false)}
                organization={selectedOrg}
                onSuccess={fetchOrganizations}
            />
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/Card";
import {
    CreditCard,
    Store,
    TrendingUp,
    ArrowUpRight,
    ArrowDownRight,
    Loader2,
    Clock,
    Zap
} from "lucide-react";
import { api } from "@/lib/api";
import { cn } from "@/lib/utils";

interface Stats {
    totalUsers: number;
    activeSubscriptions: number;
    monthlyRevenue: number;
    recentUsers: Array<{
        displayName?: string;
        email?: string;
        createdAt: string;
        subscriptionStatus?: string;
    }>;
}

export default function OverviewPage() {
    const [stats, setStats] = useState<Stats | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const fetchStats = async () => {
            try {
                const res = await api.get<{ ok: boolean; stats: Stats }>("/admin/stats");
                setStats(res.data.stats);
            } catch (error) {
                console.error("Failed to fetch stats", error);
            } finally {
                setIsLoading(false);
            }
        };
        fetchStats();
    }, []);

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-[50vh]">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
            </div>
        );
    }

    const cards = [
        {
            title: "Total Businesses",
            value: stats?.totalUsers || 0,
            icon: Store,
            description: "+12% from last month",
            trend: "up",
            color: "text-blue-600",
            bg: "bg-blue-100/50"
        },
        {
            title: "Active Subscriptions",
            value: stats?.activeSubscriptions || 0,
            icon: Zap,
            description: "+4 new today",
            trend: "up",
            color: "text-purple-600",
            bg: "bg-purple-100/50"
        },
        {
            title: "Monthly Revenue",
            value: `₹${(stats?.monthlyRevenue || 0).toLocaleString()}`,
            icon: CreditCard,
            description: "+8% growth",
            trend: "up",
            color: "text-green-600",
            bg: "bg-green-100/50"
        },
        {
            title: "Global Conversion",
            value: "18.4%",
            icon: TrendingUp,
            description: "-2% bounce rate",
            trend: "up",
            color: "text-orange-600",
            bg: "bg-orange-100/50"
        }
    ];

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex flex-col gap-1">
                <h1 className="text-3xl font-bold tracking-tight">System Overview</h1>
                <p className="text-muted-foreground">Real-time performance metrics and system activity.</p>
            </div>

            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-4">
                {cards.map((card, i) => (
                    <Card key={i} className="group relative overflow-hidden border-none shadow-sm hover:shadow-md transition-all">
                        <div className={cn("absolute inset-0 opacity-10 transition-opacity group-hover:opacity-20", card.bg)} />
                        <CardHeader className="flex flex-row items-center justify-between pb-2">
                            <CardTitle className="text-sm font-semibold text-muted-foreground uppercase tracking-wider">{card.title}</CardTitle>
                            <div className={cn("p-2 rounded-xl transition-transform group-hover:scale-110", card.bg, card.color)}>
                                <card.icon className="h-5 w-5" />
                            </div>
                        </CardHeader>
                        <CardContent>
                            <div className="text-3xl font-bold tracking-tight">{card.value}</div>
                            <div className="flex items-center gap-1 mt-1">
                                {card.trend === "up" ? (
                                    <ArrowUpRight className="h-3 w-3 text-green-600" />
                                ) : (
                                    <ArrowDownRight className="h-3 w-3 text-red-600" />
                                )}
                                <p className="text-xs text-muted-foreground">{card.description}</p>
                            </div>
                        </CardContent>
                    </Card>
                ))}
            </div>

            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-7">
                <Card className="col-span-full lg:col-span-4 border-none shadow-sm overflow-hidden bg-card/50">
                    <CardHeader className="pb-4 border-b">
                        <CardTitle className="text-lg font-bold flex items-center gap-2">
                            <Clock className="h-5 w-5 text-primary" />
                            Recent Onboarding
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="p-0">
                        <div className="divide-y">
                            {stats?.recentUsers.map((user: any, i) => (
                                <div key={i} className="flex items-center gap-4 p-4 hover:bg-muted/30 transition-colors">
                                    <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold">
                                        {(user.displayName || "U")[0]}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <p className="text-sm font-semibold truncate">{user.displayName || "New User"}</p>
                                        <p className="text-xs text-muted-foreground truncate">{user.email || "No email"}</p>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-xs font-medium">{new Date(user.createdAt).toLocaleDateString()}</p>
                                        <span className={cn(
                                            "text-[10px] font-bold uppercase tracking-wider",
                                            user.subscriptionStatus === 'active' ? "text-green-600" : "text-muted-foreground"
                                        )}>
                                            {user.subscriptionStatus || "inactive"}
                                        </span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </CardContent>
                </Card>

                <Card className="col-span-full lg:col-span-3 border-none shadow-sm bg-linear-to-br from-primary/5 to-transparent">
                    <CardHeader>
                        <CardTitle className="text-lg font-bold">System Health</CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-6">
                        <div className="space-y-2">
                            <div className="flex items-center justify-between text-sm">
                                <span className="text-muted-foreground">API Latency</span>
                                <span className="font-semibold">42ms</span>
                            </div>
                            <div className="h-2 rounded-full bg-muted overflow-hidden">
                                <div className="h-full bg-green-500 w-[95%]" />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <div className="flex items-center justify-between text-sm">
                                <span className="text-muted-foreground">DB Connection Pool</span>
                                <span className="font-semibold">8/20</span>
                            </div>
                            <div className="h-2 rounded-full bg-muted overflow-hidden">
                                <div className="h-full bg-blue-500 w-[40%]" />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <div className="flex items-center justify-between text-sm">
                                <span className="text-muted-foreground">Storage Usage</span>
                                <span className="font-semibold">12.4 GB</span>
                            </div>
                            <div className="h-2 rounded-full bg-muted overflow-hidden">
                                <div className="h-full bg-orange-500 w-[62%]" />
                            </div>
                        </div>
                    </CardContent>
                </Card>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from "@/components/ui/Card";
import { Shield, Zap, RefreshCw } from "lucide-react";
import { Switch } from "@/components/ui/Switch";
import { Button } from "@/components/ui/Button";
import { adminService, AdminSettings } from "@/services/adminService";
import { useToast } from "@/components/ui/Toast";

export default function SettingsPage() {
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [settings, setSettings] = useState<AdminSettings | null>(null);

    const { toast } = useToast();

    useEffect(() => {
        loadSettings();
    }, []);

    const loadSettings = async () => {
        setIsLoading(true);
        try {
            const data = await adminService.getSettings();
            setSettings(data);
        } catch (error) {
            console.error("Failed to load settings", error);
            toast({
                title: "Error",
                description: "Failed to load global settings",
                type: "error"
            });
        } finally {
            setIsLoading(false);
        }
    };

    const handleUpdate = async (update: Partial<AdminSettings>) => {
        if (!settings) return;
        setSettings({ ...settings, ...update });
    };

    const saveSettings = async () => {
        if (!settings) return;
        setIsSaving(true);
        try {
            await adminService.updateSettings(settings);
            toast({
                title: "Success",
                description: "Global settings updated successfully",
                type: "success"
            });
        } catch (error) {
            console.error("Failed to save settings", error);
            toast({
                title: "Error",
                description: "Failed to persist changes",
                type: "error"
            });
        } finally {
            setIsSaving(false);
        }
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <RefreshCw className="h-8 w-8 animate-spin text-primary" />
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-500 max-w-4xl">
            <div className="flex flex-col gap-1">
                <h1 className="text-3xl font-bold tracking-tight">System Settings</h1>
                <p className="text-muted-foreground text-lg">Configure global system behavior and security policies.</p>
            </div>

            <div className="space-y-6">
                <Card className="border-none shadow-sm overflow-hidden">
                    <CardHeader className="bg-muted/30 pb-6 border-b">
                        <div className="flex items-center gap-3">
                            <div className="p-2 rounded-xl bg-primary/10 text-primary">
                                <Shield className="h-6 w-6" />
                            </div>
                            <div>
                                <CardTitle className="text-xl">Authentication & Security</CardTitle>
                                <CardDescription>Manage security protocols and access controls.</CardDescription>
                            </div>
                        </div>
                    </CardHeader>
                    <CardContent className="p-6 space-y-6 divide-y">
                        <div className="flex items-center justify-between pt-0 first:pt-0">
                            <div className="space-y-1">
                                <p className="font-semibold">Developer Direct Login</p>
                                <p className="text-sm text-muted-foreground">Enable bypass login for developers in local environments.</p>
                            </div>
                            <Switch checked={true} onCheckedChange={() => { }} disabled />
                        </div>
                        <div className="flex items-center justify-between pt-6">
                            <div className="space-y-1">
                                <p className="font-semibold">Maintenance Mode</p>
                                <p className="text-sm text-muted-foreground">Redirect all non-admin users to a maintenance page.</p>
                            </div>
                            <Switch
                                checked={settings?.maintenanceMode ?? false}
                                onCheckedChange={(val) => handleUpdate({ maintenanceMode: val })}
                            />
                        </div>
                        <div className="flex items-center justify-between pt-6">
                            <div className="space-y-1">
                                <p className="font-semibold">Registration Allowed</p>
                                <p className="text-sm text-muted-foreground">Enable or disable new user registrations.</p>
                            </div>
                            <Switch
                                checked={settings?.registrationAllowed ?? false}
                                onCheckedChange={(val) => handleUpdate({ registrationAllowed: val })}
                            />
                        </div>
                    </CardContent>
                </Card>

                <Card className="border-none shadow-sm overflow-hidden">
                    <CardHeader className="bg-muted/30 pb-6 border-b">
                        <div className="flex items-center gap-3">
                            <div className="p-2 rounded-xl bg-orange-500/10 text-orange-600">
                                <Zap className="h-6 w-6" />
                            </div>
                            <div>
                                <CardTitle className="text-xl">Financial Defaults</CardTitle>
                                <CardDescription>Global defaults for financial calculations.</CardDescription>
                            </div>
                        </div>
                    </CardHeader>
                    <CardContent className="p-6 space-y-6 divide-y">
                        <div className="flex items-center justify-between pt-0">
                            <div className="space-y-1">
                                <p className="font-semibold">Global Tax Rate (%)</p>
                                <p className="text-sm text-muted-foreground">Default tax percentage applied to items (currently {settings?.globalTaxRate}%).</p>
                            </div>
                            <Button variant="outline" size="sm" onClick={() => {
                                const rate = prompt("Enter new global tax rate:", settings?.globalTaxRate.toString());
                                if (rate) handleUpdate({ globalTaxRate: parseFloat(rate) });
                            }}>Adjust</Button>
                        </div>
                        <div className="flex items-center justify-between pt-6">
                            <div className="space-y-1">
                                <p className="font-semibold">Support Email</p>
                                <p className="text-sm text-muted-foreground">Contact point for system level inquiries.</p>
                            </div>
                            <p className="font-medium text-primary underline">{settings?.supportEmail}</p>
                        </div>
                    </CardContent>
                </Card>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t">
                <Button variant="ghost" onClick={loadSettings}>Reset</Button>
                <Button
                    size="lg"
                    className="px-8 shadow-lg shadow-primary/20"
                    onClick={saveSettings}
                    disabled={isSaving}
                >
                    {isSaving ? "Saving..." : "Save Global Settings"}
                </Button>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { DataTable } from "@/components/ui/DataTable";
import { Card, CardContent } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Plus, Zap, CheckCircle2, XCircle } from "lucide-react";
import { Plan, planService } from "@/services/planService";
import { useToast } from "@/components/ui/Toast";
import { PlanDrawer } from "@/components/subscriptions/PlanDrawer";

export default function SubscriptionsPage() {
    const [plans, setPlans] = useState<Plan[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isDrawerOpen, setIsDrawerOpen] = useState(false);
    const [selectedPlan, setSelectedPlan] = useState<Plan | undefined>(undefined);
    const { toast } = useToast();

    const fetchPlans = async () => {
        setIsLoading(true);
        try {
            const data = await planService.getAll();
            setPlans(data);
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to fetch plans",
                type: "error"
            });
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchPlans();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const handleEdit = (plan: Plan) => {
        setSelectedPlan(plan);
        setIsDrawerOpen(true);
    };

    const handleCreate = () => {
        setSelectedPlan(undefined);
        setIsDrawerOpen(true);
    };

    const handleSeed = async () => {
        try {
            await planService.seedDefault();
            toast({
                title: "Success",
                description: "Default plans seeded successfully",
                type: "success"
            });
            fetchPlans();
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to seed default plans",
                type: "error"
            });
        }
    };

    const columns = [
        {
            header: "Plan Name",
            accessorKey: "name",
            cell: (plan: Plan) => (
                <div className="flex items-center gap-3">
                    <div className="h-10 w-10 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
                        <Zap className="h-5 w-5" />
                    </div>
                    <div>
                        <p className="font-semibold">{plan.name}</p>
                        <p className="text-xs text-muted-foreground">{plan.id}</p>
                    </div>
                </div>
            )
        },
        {
            header: "Price",
            accessorKey: "monthlyPrice",
            cell: (plan: Plan) => (
                <div className="font-medium">
                    {new Intl.NumberFormat('en-IN', { style: 'currency', currency: plan.currency }).format(plan.monthlyPrice)}
                    <span className="text-xs text-muted-foreground ml-1">/mo</span>
                </div>
            )
        },
        {
            header: "Features",
            accessorKey: "features",
            cell: (plan: Plan) => (
                <div className="flex -space-x-2">
                    {plan.features.slice(0, 3).map((f, i) => (
                        <div key={i} className="h-6 w-6 rounded-full bg-muted border-2 border-card flex items-center justify-center text-[10px] font-bold" title={f}>
                            {f.charAt(0).toUpperCase()}
                        </div>
                    ))}
                    {plan.features.length > 3 && (
                        <div className="h-6 w-6 rounded-full bg-primary/10 border-2 border-card flex items-center justify-center text-[10px] font-bold text-primary">
                            +{plan.features.length - 3}
                        </div>
                    )}
                </div>
            )
        },
        {
            header: "Status",
            accessorKey: "isActive",
            cell: (plan: Plan) => (
                <div className={plan.isActive ? "text-green-600 flex items-center gap-1.5" : "text-red-500 flex items-center gap-1.5"}>
                    {plan.isActive ? <CheckCircle2 className="h-4 w-4" /> : <XCircle className="h-4 w-4" />}
                    <span className="text-xs font-semibold uppercase tracking-wider">{plan.isActive ? "Active" : "Inactive"}</span>
                </div>
            )
        },
        {
            header: "Actions",
            accessorKey: "actions",
            className: "text-right",
            cell: (plan: Plan) => (
                <Button variant="ghost" size="sm" onClick={(e) => {
                    e.stopPropagation();
                    handleEdit(plan);
                }}>
                    Edit
                </Button>
            )
        }
    ];

    return (
        <div className="space-y-6">
            <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight text-foreground">Subscriptions & Plans</h1>
                    <p className="text-muted-foreground">Define business tiers and control module access.</p>
                </div>
                <div className="flex gap-3">
                    <Button variant="outline" onClick={handleSeed}>
                        Seed Defaults
                    </Button>
                    <Button onClick={handleCreate} className="h-11 px-6 shadow-lg shadow-primary/20">
                        <Plus className="mr-2 h-5 w-5" />
                        Create Plan
                    </Button>
                </div>
            </div>

            <Card className="border-none shadow-none bg-transparent">
                <CardContent className="p-0">
                    <DataTable
                        columns={columns}
                        data={plans}
                        isLoading={isLoading}
                        onRowClick={handleEdit}
                        emptyMessage="No plans configured. Seed defaults to get started."
                    />
                </CardContent>
            </Card>

            <PlanDrawer
                isOpen={isDrawerOpen}
                onClose={() => setIsDrawerOpen(false)}
                plan={selectedPlan}
                onSuccess={fetchPlans}
            />
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { DataTable } from "@/components/ui/DataTable";
import { Card, CardContent } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Store, Receipt, AlertCircle, CheckCircle2, Clock } from "lucide-react";
import { Transaction, transactionService } from "@/services/transactionService";
import { useToast } from "@/components/ui/Toast";
import { cn } from "@/lib/utils";

export default function TransactionsPage() {
    const [transactions, setTransactions] = useState<Transaction[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState("");
    const { toast } = useToast();

    const fetchTransactions = async () => {
        setIsLoading(true);
        try {
            const data = await transactionService.getAll();
            setTransactions(data);
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to fetch transactions",
                type: "error"
            });
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchTransactions();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const filteredTransactions = transactions.filter(t =>
        t.organizationName?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        t.id.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const columns = [
        {
            header: "Transaction ID",
            accessorKey: "id",
            cell: (t: Transaction) => (
                <div className="flex items-center gap-2">
                    <Receipt className="h-4 w-4 text-muted-foreground" />
                    <span className="font-mono text-xs">{t.id}</span>
                </div>
            )
        },
        {
            header: "Organization",
            accessorKey: "organizationName",
            cell: (t: Transaction) => (
                <div className="flex items-center gap-2">
                    <Store className="h-4 w-4 text-primary/60" />
                    <span className="font-medium">{t.organizationName || "Unknown Org"}</span>
                </div>
            )
        },
        {
            header: "Type",
            accessorKey: "type",
            cell: (t: Transaction) => (
                <span className={cn(
                    "px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider",
                    t.type === 'SALE' ? "bg-green-100 text-green-700" : "bg-blue-100 text-blue-700"
                )}>
                    {t.type}
                </span>
            )
        },
        {
            header: "Amount",
            accessorKey: "totalAmount",
            cell: (t: Transaction) => (
                <span className="font-bold text-foreground">
                    ₹{t.totalAmount.toLocaleString()}
                </span>
            )
        },
        {
            header: "Payment",
            accessorKey: "paymentStatus",
            cell: (t: Transaction) => (
                <div className={cn(
                    "flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-wider",
                    {
                        "text-green-600": t.paymentStatus === 'PAID',
                        "text-yellow-600": t.paymentStatus === 'PARTIAL',
                        "text-red-600": t.paymentStatus === 'UNPAID'
                    }
                )}>
                    {t.paymentStatus === 'PAID' && <CheckCircle2 className="h-3 w-3" />}
                    {t.paymentStatus === 'PARTIAL' && <Clock className="h-3 w-3" />}
                    {t.paymentStatus === 'UNPAID' && <AlertCircle className="h-3 w-3" />}
                    {t.paymentStatus}
                </div>
            )
        },
        {
            header: "Date",
            accessorKey: "createdAt",
            cell: (t: Transaction) => (
                <span className="text-muted-foreground">
                    {new Date(t.createdAt).toLocaleDateString()}
                </span>
            )
        }
    ];

    return (
        <div className="space-y-6">
            <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight text-foreground">Transactions</h1>
                    <p className="text-muted-foreground">Global audit of all bills and financial activity.</p>
                </div>
                <div className="flex gap-2">
                    <Button variant="outline" onClick={fetchTransactions}>
                        Refresh
                    </Button>
                </div>
            </div>

            <Card className="border-none shadow-none bg-transparent">
                <CardContent className="p-0">
                    <DataTable
                        columns={columns}
                        data={filteredTransactions}
                        isLoading={isLoading}
                        searchPlaceholder="Filter by organization or ID..."
                        searchValue={searchQuery}
                        onSearchChange={setSearchQuery}
                    />
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/Card";
import {
    Wallet,
    TrendingUp,
    ArrowUpRight,
    ArrowDownRight,
    Building2,
    Briefcase,
    DollarSign,
    RefreshCw
} from "lucide-react";
import { DataTable } from "@/components/ui/DataTable";
import { Button } from "@/components/ui/Button";
import { adminService, TreasuryStats } from "@/services/adminService";
import { cn } from "@/lib/utils";

export default function TreasuryPage() {
    const [isLoading, setIsLoading] = useState(true);
    const [statsData, setStatsData] = useState<TreasuryStats | null>(null);
    const [accounts, setAccounts] = useState<any[]>([]);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        setIsLoading(true);
        try {
            const res = await adminService.getTreasuryStats();
            setStatsData(res.stats);
            setAccounts(res.accounts.map(acc => ({
                id: acc.id,
                name: acc.name,
                type: "BANK",
                balance: `₹${acc.currentBalance.toLocaleString()}`,
                org: acc.userId.substring(0, 8), // Simplified org name
                lastSync: "Just now"
            })));
        } catch (error) {
            console.error("Failed to load treasury data", error);
        } finally {
            setIsLoading(false);
        }
    };

    const stats = [
        {
            title: "Total Liquidity",
            value: statsData ? `₹${(statsData.totalLiquidity / 100000).toFixed(2)}L` : "₹0",
            icon: Wallet,
            trend: "up",
            percentage: "+12%"
        },
        {
            title: "Institutional Reserve",
            value: statsData ? `₹${(statsData.institutionalReserve / 100000).toFixed(2)}L` : "₹0",
            icon: Briefcase,
            trend: "up",
            percentage: "+5%"
        },
        {
            title: "Pending Settlements",
            value: statsData ? `₹${(statsData.settlementsPending).toLocaleString()}` : "0",
            icon: DollarSign,
            trend: "down",
            percentage: "-2%"
        },
        {
            title: "Net Cash Flow",
            value: statsData ? `₹${(statsData.netCashFlow / 100000).toFixed(1)}L` : "₹0",
            icon: Building2,
            trend: "up",
            percentage: "+8%"
        },
    ];

    const columns = [
        { header: "Account Name", accessorKey: "name" },
        { header: "Type", accessorKey: "type" },
        { header: "Balance", accessorKey: "balance" },
        { header: "Organization (UID)", accessorKey: "org" },
        { header: "Last Sync", accessorKey: "lastSync" },
    ];

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Treasury</h1>
                    <p className="text-muted-foreground">Global financial liquidity and account management.</p>
                </div>
                <Button variant="outline" className="gap-2" onClick={loadData} disabled={isLoading}>
                    <RefreshCw className={cn("h-4 w-4", isLoading && "animate-spin")} />
                    Sync Accounts
                </Button>
            </div>

            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-4">
                {stats.map((stat, i) => (
                    <Card key={i} className="border-none shadow-sm overflow-hidden group">
                        <CardHeader className="flex flex-row items-center justify-between pb-2">
                            <CardTitle className="text-sm font-semibold text-muted-foreground uppercase tracking-wider">{stat.title}</CardTitle>
                            <div className="p-2 rounded-xl bg-primary/10 text-primary transition-transform group-hover:scale-110">
                                <stat.icon className="h-5 w-5" />
                            </div>
                        </CardHeader>
                        <CardContent>
                            <div className="text-3xl font-bold tracking-tight">{stat.value}</div>
                            <div className="flex items-center gap-1 mt-1">
                                {stat.trend === "up" ? (
                                    <TrendingUp className="h-3 w-3 text-green-600" />
                                ) : (
                                    <ArrowDownRight className="h-3 w-3 text-red-600" />
                                )}
                                <p className="text-xs text-muted-foreground">
                                    <span className={stat.trend === "up" ? "text-green-600 font-medium" : "text-red-600 font-medium"}>
                                        {stat.percentage}
                                    </span>{" "}
                                    from last period
                                </p>
                            </div>
                        </CardContent>
                    </Card>
                ))}
            </div>

            <Card className="border-none shadow-sm overflow-hidden bg-card/50">
                <CardHeader className="pb-4 border-b">
                    <CardTitle className="text-lg font-bold">Account Balances</CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                    <DataTable
                        columns={columns}
                        data={accounts}
                        isLoading={isLoading}
                        searchPlaceholder="Filter accounts..."
                    />
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState } from "react";
import { useUsers } from "@/hooks/useUsers";
import { Button } from "@/components/ui/Button";
import { UserActionDialog } from "@/components/users/UserActionDialog";
import { User } from "@/types";
import { MoreHorizontal, Shield, CreditCard, Search } from "lucide-react";
import { Input } from "@/components/ui/Input";

export default function UsersPage() {
    const { data: users, isLoading } = useUsers(100);
    const [selectedUser, setSelectedUser] = useState<User | undefined>(undefined);
    const [searchTerm, setSearchTerm] = useState("");

    const filteredUsers = users?.filter(user =>
        user.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        user.displayName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        user.businessName?.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const handleManage = (user: User) => {
        setSelectedUser(user);
    };

    if (isLoading) return <div className="p-8">Loading users...</div>;

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight">Users</h2>
                    <p className="text-muted-foreground">Manage users, roles, and subscriptions.</p>
                </div>
            </div>

            <div className="flex items-center gap-2 max-w-sm">
                <Search className="w-4 h-4 text-muted-foreground" />
                <Input
                    placeholder="Search users..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>

            <div className="rounded-md border bg-card">
                <div className="relative w-full overflow-auto">
                    <table className="w-full caption-bottom text-sm">
                        <thead className="[&_tr]:border-b">
                            <tr className="border-b transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted">
                                <th className="h-12 px-4 text-left align-middle font-medium text-muted-foreground">User</th>
                                <th className="h-12 px-4 text-left align-middle font-medium text-muted-foreground">Role</th>
                                <th className="h-12 px-4 text-left align-middle font-medium text-muted-foreground">Subscription</th>
                                <th className="h-12 px-4 text-left align-middle font-medium text-muted-foreground">Status</th>
                                <th className="h-12 px-4 text-right align-middle font-medium text-muted-foreground">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="[&_tr:last-child]:border-0">
                            {filteredUsers?.map((user) => (
                                <tr key={user.uid} className="border-b transition-colors hover:bg-muted/50">
                                    <td className="p-4 align-middle">
                                        <div className="flex flex-col">
                                            <span className="font-medium">{user.displayName || "Unknown"}</span>
                                            <span className="text-xs text-muted-foreground">{user.email}</span>
                                            {user.businessName && <span className="text-xs text-muted-foreground italic">{user.businessName}</span>}
                                        </div>
                                    </td>
                                    <td className="p-4 align-middle">
                                        <div className="flex items-center gap-1">
                                            <Shield className="w-3 h-3 text-muted-foreground" />
                                            <span className="capitalize">{user.role}</span>
                                        </div>
                                    </td>
                                    <td className="p-4 align-middle">
                                        <div className="flex flex-col">
                                            <span className="font-medium">{user.subscriptionPlanName || "Free Plan"}</span>
                                            {user.subscriptionEndsAt && (
                                                <span className="text-xs text-muted-foreground">
                                                    Ends: {new Date(user.subscriptionEndsAt).toLocaleDateString()}
                                                </span>
                                            )}
                                        </div>
                                    </td>
                                    <td className="p-4 align-middle">
                                        <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-semibold
                        ${user.subscriptionStatus === 'active' ? 'bg-green-100 text-green-800' :
                                                user.subscriptionStatus === 'expired' ? 'bg-yellow-100 text-yellow-800' : 'bg-gray-100 text-gray-800'}
                    `}>
                                            {user.subscriptionStatus}
                                        </span>
                                    </td>
                                    <td className="p-4 align-middle text-right">
                                        <Button variant="ghost" size="sm" onClick={() => handleManage(user)}>
                                            Manage
                                        </Button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

            <UserActionDialog
                isOpen={!!selectedUser}
                onClose={() => setSelectedUser(undefined)}
                user={selectedUser}
            />
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Sheet } from "@/components/ui/Sheet";
import { Input } from "@/components/ui/Input";
import { Button } from "@/components/ui/Button";
import { Offer, offerService } from "@/services/offerService";
import { useToast } from "@/components/ui/Toast";
import { Switch } from "@/components/ui/Switch";
import { Megaphone, Target, Image as ImageIcon, Link as LinkIcon, Users } from "lucide-react";

interface OfferDrawerProps {
    isOpen: boolean;
    onClose: () => void;
    offer?: Offer;
    onSuccess: () => void;
}

export function OfferDrawer({ isOpen, onClose, offer, onSuccess }: OfferDrawerProps) {
    const [formData, setFormData] = useState<Partial<Offer>>({
        id: "",
        title: "",
        message: "",
        audience: "all",
        isActive: true,
        priority: 0,
        bannerUrl: "",
        ctaText: "",
        ctaRoute: "",
    });
    const [isLoading, setIsLoading] = useState(false);
    const { toast } = useToast();

    useEffect(() => {
        if (offer) {
            setFormData(offer);
        } else {
            setFormData({
                id: `off_${Date.now()}`,
                title: "",
                message: "",
                audience: "all",
                isActive: true,
                priority: 0,
                bannerUrl: "",
                ctaText: "",
                ctaRoute: "",
            });
        }
    }, [offer, isOpen]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);

        try {
            if (offer) {
                await offerService.upsert(offer.id, formData);
                toast({
                    title: "Success",
                    description: "Banner updated successfully",
                    type: "success"
                });
            } else {
                await offerService.create(formData);
                toast({
                    title: "Success",
                    description: "Banner created successfully",
                    type: "success"
                });
            }
            onSuccess();
            onClose();
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to save banner",
                type: "error"
            });
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <Sheet
            isOpen={isOpen}
            onClose={onClose}
            title={offer ? "Edit Banner" : "Create New Banner"}
            description={offer ? `Updating banner: ${offer.title}` : "Create a system-wide notification or promotional offer."}
            footer={
                <div className="flex gap-3 justify-end w-full">
                    <Button variant="ghost" onClick={onClose} disabled={isLoading}>
                        Cancel
                    </Button>
                    <Button onClick={handleSubmit} isLoading={isLoading}>
                        {offer ? "Save Changes" : "Publish Banner"}
                    </Button>
                </div>
            }
        >
            <form onSubmit={handleSubmit} className="space-y-8">
                <div className="space-y-4">
                    <h3 className="text-sm font-bold uppercase tracking-wider text-muted-foreground flex items-center gap-2">
                        <Megaphone className="h-4 w-4" />
                        Content & Layout
                    </h3>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Banner Title</label>
                        <Input
                            placeholder="e.g. 50% Off Annual Plans"
                            value={formData.title}
                            onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                            required
                        />
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Message / Description</label>
                        <Input
                            placeholder="Detailed text for the banner..."
                            value={formData.message}
                            onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                            required
                        />
                    </div>
                </div>

                <div className="space-y-4">
                    <h3 className="text-sm font-bold uppercase tracking-wider text-muted-foreground flex items-center gap-2">
                        <Target className="h-4 w-4" />
                        Targeting
                    </h3>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Audience</label>
                        <select 
                            className="w-full h-10 px-3 rounded-xl border border-input bg-background focus:ring-2 focus:ring-primary/20 outline-none transition-all text-sm"
                            value={formData.audience}
                            onChange={(e) => setFormData({ ...formData, audience: e.target.value as any })}
                        >
                            <option value="all">All Users</option>
                            <option value="active_subscribers">Active Subscribers Only</option>
                            <option value="inactive_subscribers">Inactive Users Only</option>
                        </select>
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Priority (Higher = Top)</label>
                        <Input
                            type="number"
                            placeholder="0"
                            value={formData.priority}
                            onChange={(e) => setFormData({ ...formData, priority: Number(e.target.value) })}
                        />
                    </div>
                </div>

                <div className="space-y-4">
                    <h3 className="text-sm font-bold uppercase tracking-wider text-muted-foreground flex items-center gap-2">
                        <LinkIcon className="h-4 w-4" />
                        CTA & Media
                    </h3>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Banner Image URL (Optional)</label>
                        <div className="relative">
                            <ImageIcon className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                            <Input
                                className="pl-9"
                                placeholder="https://..."
                                value={formData.bannerUrl || ""}
                                onChange={(e) => setFormData({ ...formData, bannerUrl: e.target.value })}
                            />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-sm font-medium">CTA Button Text</label>
                            <Input
                                placeholder="e.g. Upgrade Now"
                                value={formData.ctaText || ""}
                                onChange={(e) => setFormData({ ...formData, ctaText: e.target.value })}
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium">CTA Route / Link</label>
                            <Input
                                placeholder="e.g. /subscription"
                                value={formData.ctaRoute || ""}
                                onChange={(e) => setFormData({ ...formData, ctaRoute: e.target.value })}
                            />
                        </div>
                    </div>
                </div>

                <div className="flex items-center justify-between p-4 rounded-xl bg-muted/50">
                    <div className="space-y-0.5">
                        <p className="text-sm font-semibold">Live Status</p>
                        <p className="text-xs text-muted-foreground">Make this banner visible immediately.</p>
                    </div>
                    <Switch
                        checked={formData.isActive || false}
                        onCheckedChange={(checked) => setFormData({ ...formData, isActive: checked })}
                    />
                </div>
            </form>
        </Sheet>
    );
}

"use client";

import React from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import {
    Users,
    CreditCard,
    LayoutDashboard,
    FileText,
    ChevronLeft,
    Menu,
    X,
    Store,
    ShieldCheck,
    Box,
    FileSpreadsheet,
    Wallet,
    Receipt,
    Megaphone,
    BarChart3,
    History,
    Settings,
    UserCircle
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useSidebar } from "@/components/providers/SidebarProvider";

interface NavItem {
    href: string;
    label: string;
    icon: React.ElementType;
}

interface NavCategory {
    label: string;
    items: NavItem[];
}

const navCategories: NavCategory[] = [
    {
        label: "Management",
        items: [
            { href: "/dashboard", label: "Overview", icon: LayoutDashboard },
            { href: "/organizations", label: "Organizations", icon: Store },
            { href: "/users", label: "Users", icon: Users },
            { href: "/staff", label: "Staff & Roles", icon: ShieldCheck },
        ]
    },
    {
        label: "Operations",
        items: [
            { href: "/transactions", label: "Transactions", icon: FileSpreadsheet },
            { href: "/inventory", label: "Inventory", icon: Box },
            { href: "/templates", label: "Bill Templates", icon: FileText },
        ]
    },
    {
        label: "Finance",
        items: [
            { href: "/subscriptions", label: "Subscriptions", icon: CreditCard },
            { href: "/treasury", label: "Treasury", icon: Wallet },
            { href: "/payroll", label: "Payroll", icon: Receipt },
        ]
    },
    {
        label: "Marketing",
        items: [
            { href: "/banners", label: "Banners & Offers", icon: Megaphone },
        ]
    },
    {
        label: "System",
        items: [
            { href: "/analytics", label: "Analytics", icon: BarChart3 },
            { href: "/audit-logs", label: "Audit Logs", icon: History },
            { href: "/settings", label: "Settings", icon: Settings },
        ]
    }
];

export function Sidebar() {
    const pathname = usePathname();
    const { isCollapsed, toggleCollapsed, isMobileOpen, setMobileOpen } = useSidebar();

    const SidebarContent = (
        <div className="flex flex-col h-full bg-card border-r shadow-sm">
            {/* Header */}
            <div className={cn(
                "flex items-center h-16 px-6 border-b shrink-0 transition-all duration-300",
                isCollapsed ? "justify-center px-2" : "justify-between"
            )}>
                {!isCollapsed && (
                    <motion.span
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        className="text-xl font-bold text-primary truncate"
                    >
                        Vahi Admin
                    </motion.span>
                )}
                <button
                    onClick={toggleCollapsed}
                    className="p-2 rounded-lg hover:bg-muted text-muted-foreground transition-colors hidden lg:flex"
                >
                    <ChevronLeft className={cn("h-5 w-5 transition-transform duration-300", isCollapsed && "rotate-180")} />
                </button>
                <button
                    onClick={() => setMobileOpen(false)}
                    className="p-2 rounded-lg hover:bg-muted text-muted-foreground transition-colors lg:hidden"
                >
                    <X className="h-5 w-5" />
                </button>
            </div>

            {/* Navigation */}
            <nav className="flex-1 overflow-y-auto overflow-x-hidden p-4 space-y-6 custom-scrollbar">
                {navCategories.map((category) => (
                    <div key={category.label} className="space-y-2">
                        {!isCollapsed && (
                            <h3 className="px-4 text-[11px] font-bold uppercase tracking-wider text-muted-foreground/60 transition-all">
                                {category.label}
                            </h3>
                        )}
                        <div className="space-y-1">
                            {category.items.map((item) => {
                                const Icon = item.icon;
                                const isActive = pathname === item.href || pathname.startsWith(item.href + "/");
                                return (
                                    <Link
                                        key={item.href}
                                        href={item.href}
                                        onClick={() => setMobileOpen(false)}
                                        className={cn(
                                            "flex items-center gap-3 px-4 py-2.5 rounded-xl text-sm font-medium transition-all group relative",
                                            isActive
                                                ? "bg-primary/10 text-primary shadow-sm"
                                                : "text-muted-foreground hover:bg-muted hover:text-foreground",
                                            isCollapsed && "justify-center px-2"
                                        )}
                                    >
                                        <Icon className={cn("h-5 w-5 shrink-0 transition-transform group-hover:scale-110", isActive ? "text-primary" : "text-muted-foreground")} />
                                        {!isCollapsed && <span>{item.label}</span>}
                                        {isCollapsed && (
                                            <div className="absolute left-full ml-4 px-2 py-1 bg-popover text-popover-foreground text-xs rounded opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity whitespace-nowrap z-50 shadow-md border">
                                                {item.label}
                                            </div>
                                        )}
                                    </Link>
                                );
                            })}
                        </div>
                    </div>
                ))}
            </nav>

            {/* Footer */}
            <div className={cn(
                "p-4 border-t shrink-0 transition-all",
                isCollapsed ? "items-center" : ""
            )}>
                <div className={cn(
                    "flex items-center gap-3 p-2 rounded-xl bg-muted/50 transition-all",
                    isCollapsed ? "justify-center" : ""
                )}>
                    <div className="h-8 w-8 rounded-full bg-primary/20 flex items-center justify-center text-primary font-bold overflow-hidden">
                        <UserCircle className="h-6 w-6" />
                    </div>
                    {!isCollapsed && (
                        <div className="flex-1 min-w-0">
                            <p className="text-sm font-semibold truncate leading-none">Admin User</p>
                            <p className="text-[11px] text-muted-foreground truncate uppercase mt-1">Super Admin</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );

    return (
        <>
            {/* Desktop Sidebar */}
            <aside className={cn(
                "hidden lg:flex flex-col h-screen sticky top-0 transition-all duration-300 z-40",
                isCollapsed ? "w-20" : "w-64"
            )}>
                {SidebarContent}
            </aside>

            {/* Mobile Sidebar */}
            <AnimatePresence>
                {isMobileOpen && (
                    <>
                        <motion.div
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            onClick={() => setMobileOpen(false)}
                            className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50 lg:hidden"
                        />
                        <motion.aside
                            initial={{ x: "-100%" }}
                            animate={{ x: 0 }}
                            exit={{ x: "-100%" }}
                            transition={{ type: "spring", damping: 25, stiffness: 200 }}
                            className="fixed inset-y-0 left-0 w-64 z-50 lg:hidden"
                        >
                            {SidebarContent}
                        </motion.aside>
                    </>
                )}
            </AnimatePresence>
        </>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Sheet } from "@/components/ui/Sheet";
import { Input } from "@/components/ui/Input";
import { Button } from "@/components/ui/Button";
import { Organization, organizationService } from "@/services/organizationService";
import { useToast } from "@/components/ui/Toast";
import { Switch } from "@/components/ui/Switch";

interface OrganizationDrawerProps {
    isOpen: boolean;
    onClose: () => void;
    organization?: Organization;
    onSuccess: () => void;
}

export function OrganizationDrawer({ isOpen, onClose, organization, onSuccess }: OrganizationDrawerProps) {
    const [formData, setFormData] = useState<Partial<Organization>>({
        name: "",
        code: "",
        gstNumber: "",
        address: "",
        phoneNumber: "",
        email: "",
        currency: "INR",
        isActive: true,
    });
    const [isLoading, setIsLoading] = useState(false);
    const { toast } = useToast();

    useEffect(() => {
        if (organization) {
            setFormData(organization);
        } else {
            setFormData({
                name: "",
                code: "",
                gstNumber: "",
                address: "",
                phoneNumber: "",
                email: "",
                currency: "INR",
                isActive: true,
            });
        }
    }, [organization, isOpen]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);

        try {
            if (organization) {
                await organizationService.update(organization.id, formData);
                toast({
                    title: "Success",
                    description: "Organization updated successfully",
                    type: "success"
                });
            } else {
                await organizationService.create(formData);
                toast({
                    title: "Success",
                    description: "Organization created successfully",
                    type: "success"
                });
            }
            onSuccess();
            onClose();
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to save organization",
                type: "error"
            });
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <Sheet
            isOpen={isOpen}
            onClose={onClose}
            title={organization ? "Edit Organization" : "Create Organization"}
            description={organization ? `Managing ${organization.name}` : "Add a new business to the system."}
            footer={
                <div className="flex gap-3 justify-end w-full">
                    <Button variant="ghost" onClick={onClose} disabled={isLoading}>
                        Cancel
                    </Button>
                    <Button onClick={handleSubmit} isLoading={isLoading}>
                        {organization ? "Save Changes" : "Create Organization"}
                    </Button>
                </div>
            }
        >
            <form onSubmit={handleSubmit} className="space-y-6">
                <div className="space-y-4">
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Business Name</label>
                        <Input
                            placeholder="e.g. Vahi Mart"
                            value={formData.name}
                            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
