                    <div className="space-y-2">
                        <label className="text-sm font-medium">Internal Code</label>
                        <Input
                            placeholder="e.g. VMART01"
                            value={formData.code}
                            onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                            required
                        />
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">GST Number (Optional)</label>
                        <Input
                            placeholder="e.g. 07AAAAA0000A1Z5"
                            value={formData.gstNumber || ""}
                            onChange={(e) => setFormData({ ...formData, gstNumber: e.target.value })}
                        />
                    </div>
                </div>

                <div className="h-px bg-muted" />

                <div className="space-y-4">
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Email Address</label>
                        <Input
                            type="email"
                            placeholder="admin@business.com"
                            value={formData.email || ""}
                            onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                        />
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Phone Number</label>
                        <Input
                            placeholder="+91 99999 99999"
                            value={formData.phoneNumber || ""}
                            onChange={(e) => setFormData({ ...formData, phoneNumber: e.target.value })}
                        />
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Business Address</label>
                        <Input
                            placeholder="Full address here..."
                            value={formData.address || ""}
                            onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                        />
                    </div>
                </div>

                <div className="h-px bg-muted" />

                <div className="flex items-center justify-between p-4 rounded-xl bg-muted/50">
                    <div className="space-y-0.5">
                        <p className="text-sm font-semibold">Active Status</p>
                        <p className="text-xs text-muted-foreground">Toggle organization visibility and access.</p>
                    </div>
                    <Switch
                        checked={formData.isActive || false}
                        onCheckedChange={(checked) => setFormData({ ...formData, isActive: checked })}
                    />
                </div>
            </form>
        </Sheet>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Sheet } from "@/components/ui/Sheet";
import { Input } from "@/components/ui/Input";
import { Button } from "@/components/ui/Button";
import { Plan, planService } from "@/services/planService";
import { useToast } from "@/components/ui/Toast";
import { Switch } from "@/components/ui/Switch";
import { ShieldCheck, Box, Receipt, Wallet, Megaphone, BarChart3 } from "lucide-react";

interface PlanDrawerProps {
    isOpen: boolean;
    onClose: () => void;
    plan?: Plan;
    onSuccess: () => void;
}

const MODULE_FEATURES = [
    { id: "feature_inventory", label: "Inventory Management", icon: Box, description: "Stock tracking, HSN codes, and low stock alerts." },
    { id: "feature_payroll", label: "Staff & Payroll", icon: Receipt, description: "Attendance, salary runs, and payslip generation." },
    { id: "feature_treasury", label: "Treasury & Banking", icon: Wallet, description: "Bank ledgers and voucher management." },
    { id: "feature_marketing", label: "Banners & Marketing", icon: Megaphone, description: "Control system-wide promotional banners." },
    { id: "feature_analytics", label: "Advanced Analytics", icon: BarChart3, description: "Deep-dive reports and trend analysis." },
];

export function PlanDrawer({ isOpen, onClose, plan, onSuccess }: PlanDrawerProps) {
    const [formData, setFormData] = useState<Partial<Plan>>({
        id: "",
        name: "",
        description: "",
        monthlyPrice: 0,
        currency: "INR",
        isActive: true,
        displayOrder: 0,
        features: [],
    });
    const [isLoading, setIsLoading] = useState(false);
    const { toast } = useToast();

    useEffect(() => {
        if (plan) {
            setFormData(plan);
        } else {
            setFormData({
                id: `plan_${Date.now()}`,
                name: "",
                description: "",
                monthlyPrice: 0,
                currency: "INR",
                isActive: true,
                displayOrder: 0,
                features: [],
            });
        }
    }, [plan, isOpen]);

    const handleFeatureToggle = (featureId: string) => {
        const currentFeatures = formData.features || [];
        if (currentFeatures.includes(featureId)) {
            setFormData({ ...formData, features: currentFeatures.filter(f => f !== featureId) });
        } else {
            setFormData({ ...formData, features: [...currentFeatures, featureId] });
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);

        try {
            if (plan) {
                await planService.upsert(plan.id, formData);
                toast({
                    title: "Success",
                    description: "Plan updated successfully",
                    type: "success"
                });
            } else {
                await planService.create(formData);
                toast({
                    title: "Success",
                    description: "Plan created successfully",
                    type: "success"
                });
            }
            onSuccess();
            onClose();
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to save plan",
                type: "error"
            });
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <Sheet
            isOpen={isOpen}
            onClose={onClose}
            title={plan ? "Edit Plan" : "Create New Plan"}
            description={plan ? `Updating ${plan.name} configuration` : "Define a new subscription tier."}
            footer={
                <div className="flex gap-3 justify-end w-full">
                    <Button variant="ghost" onClick={onClose} disabled={isLoading}>
                        Cancel
                    </Button>
                    <Button onClick={handleSubmit} isLoading={isLoading}>
                        {plan ? "Save Plan" : "Create Plan"}
                    </Button>
                </div>
            }
        >
            <form onSubmit={handleSubmit} className="space-y-8">
                <div className="space-y-4">
                    <h3 className="text-sm font-bold uppercase tracking-wider text-muted-foreground">General Info</h3>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="col-span-2 space-y-2">
                            <label className="text-sm font-medium">Plan Name</label>
                            <Input
                                placeholder="e.g. Growth Plan"
                                value={formData.name}
                                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                required
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Monthly Price</label>
                            <Input
                                type="number"
                                placeholder="499"
                                value={formData.monthlyPrice}
                                onChange={(e) => setFormData({ ...formData, monthlyPrice: Number(e.target.value) })}
                                required
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Currency</label>
                            <Input
                                placeholder="INR"
                                value={formData.currency}
                                onChange={(e) => setFormData({ ...formData, currency: e.target.value })}
                                required
                            />
                        </div>
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Description</label>
                        <Input
                            placeholder="Briefly describe what's included..."
                            value={formData.description}
                            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                        />
                    </div>
                </div>

                <div className="space-y-4">
                    <div className="flex items-center justify-between">
                        <h3 className="text-sm font-bold uppercase tracking-wider text-muted-foreground flex items-center gap-2">
                            <ShieldCheck className="h-4 w-4" />
                            Module Access Control
                        </h3>
                    </div>
                    <p className="text-xs text-muted-foreground">Select which modules companies on this plan can access.</p>

                    <div className="space-y-3">
                        {MODULE_FEATURES.map((feature) => {
                            const Icon = feature.icon;
                            const isEnabled = formData.features?.includes(feature.id);
                            return (
                                <div
                                    key={feature.id}
                                    className={`flex items-center justify-between p-4 rounded-xl border transition-all ${isEnabled ? "bg-primary/5 border-primary/20" : "bg-card border-border"
                                        }`}
                                >
                                    <div className="flex items-center gap-3">
                                        <div className={`h-10 w-10 rounded-lg flex items-center justify-center transition-colors ${isEnabled ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground"
                                            }`}>
                                            <Icon className="h-5 w-5" />
                                        </div>
                                        <div className="space-y-0.5">
                                            <p className="text-sm font-semibold">{feature.label}</p>
                                            <p className="text-[11px] text-muted-foreground leading-tight max-w-[200px]">{feature.description}</p>
                                        </div>
                                    </div>
                                    <Switch
                                        checked={isEnabled ?? false}
                                        onCheckedChange={() => handleFeatureToggle(feature.id)}
                                    />
                                </div>
                            );
                        })}
                    </div>
                </div>

                <div className="flex items-center justify-between p-4 rounded-xl bg-muted/50">
                    <div className="space-y-0.5">
                        <p className="text-sm font-semibold">Public Visibility</p>
                        <p className="text-xs text-muted-foreground">Whether this plan is visible to businesses.</p>
                    </div>
                    <Switch
                        checked={!!formData.isActive}
                        onCheckedChange={(checked) => setFormData({ ...formData, isActive: checked })}
                    />
                </div>
            </form>
        </Sheet>
    );
}

"use client";

import * as React from "react";
import { motion, AnimatePresence } from "framer-motion";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";

interface SheetProps {
    isOpen: boolean;
    onClose: () => void;
    title?: string;
    description?: string;
    children: React.ReactNode;
    footer?: React.ReactNode;
}

export function Sheet({ isOpen, onClose, title, description, children, footer }: SheetProps) {
    // Close on Escape key
    React.useEffect(() => {
        const handleEscape = (e: KeyboardEvent) => {
            if (e.key === "Escape") onClose();
        };
        if (isOpen) {
            window.addEventListener("keydown", handleEscape);
            document.body.style.overflow = "hidden";
        }
        return () => {
            window.removeEventListener("keydown", handleEscape);
            document.body.style.overflow = "unset";
        };
    }, [isOpen, onClose]);

    return (
        <AnimatePresence>
            {isOpen && (
                <>
                    {/* Backdrop */}
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={onClose}
                        className="fixed inset-0 z-50 bg-black/40 backdrop-blur-sm"
                    />
                    {/* Sheet Content */}
                    <motion.div
                        initial={{ x: "100%" }}
                        animate={{ x: 0 }}
                        exit={{ x: "100%" }}
                        transition={{ type: "spring", damping: 25, stiffness: 200 }}
                        className="fixed inset-y-0 right-0 z-50 w-full max-w-md bg-card shadow-2xl flex flex-col"
                    >
                        <div className="flex items-center justify-between p-6 border-b">
                            <div>
                                {title && <h2 className="text-lg font-semibold">{title}</h2>}
                                {description && <p className="text-sm text-muted-foreground">{description}</p>}
                            </div>
                            <button
                                onClick={onClose}
                                className="rounded-full p-2 hover:bg-muted transition-colors"
                            >
                                <X className="h-5 w-5" />
                            </button>
                        </div>
                        <div className="flex-1 overflow-y-auto p-6">
                            {children}
                        </div>
                        {footer && (
                            <div className="p-6 border-t mt-auto">
                                {footer}
                            </div>
                        )}
                    </motion.div>
                </>
            )}
        </AnimatePresence>
    );
}

import { api } from "@/lib/api";

export interface TreasuryStats {
    totalLiquidity: number;
    settlementsPending: number;
    institutionalReserve: number;
    netCashFlow: number;
}

export interface PayrollStats {
    totalDisbursed: number;
    totalStaff: number;
    avgSalary: number;
    activeBatches: number;
}

export interface SystemMetrics {
    totalUsers: number;
    activeSubscriptions: number;
    monthlyRevenue: number;
    systemHealth: number;
    userGrowth: number;
    revenueGrowth: number;
}

export interface AdminSettings {
    maintenanceMode: boolean;
    registrationAllowed: boolean;
    globalTaxRate: number;
    supportEmail: string;
}

export const adminService = {
    getTreasuryStats: async () => {
        const response = await api.get<{ ok: boolean; stats: TreasuryStats; accounts: any[] }>("/admin/treasury/stats");
        return response.data;
    },
    getPayrollStats: async () => {
        const response = await api.get<{ ok: boolean; stats: PayrollStats; latestBatches: any[] }>("/admin/payroll/stats");
        return response.data;
    },
    getAnalyticsExtended: async () => {
        const response = await api.get<{ ok: boolean; metrics: SystemMetrics }>("/admin/analytics/extended");
        return response.data;
    },
    getSettings: async () => {
        const response = await api.get<{ ok: boolean; settings: AdminSettings }>("/admin/settings");
        return response.data.settings;
    },
    updateSettings: async (settings: Partial<AdminSettings>) => {
        const response = await api.patch<{ ok: boolean }>("/admin/settings", settings);
        return response.data;
    }
};
